110		public void appticsFeedback()
111		{
112			try
113			{
114				User currentUser = checkCurrentUser();
115	
116				@SuppressWarnings("unchecked")
117				ArrayList<UploadedFileItem> fileItems = (ArrayList<UploadedFileItem>) request.getAttribute(SecurityUtil.MULTIPART_FORM_REQUEST);
118	
119				if(CommonUtil.isEmpty(subject) && CommonUtil.isEmpty(description) && CommonUtil.isEmpty(fileItems))
120				{
121					ClientWriter.sendErrorResponse(response, AppticsConstants.INVALID_DATA, AppticsConstants.INVALID_DATA_MSG, AppticsConstants.SC_BAD_REQUEST);
122					return;
123				}
124	
125				JSONArray  attachments = new JSONArray();
126				if(!CommonUtil.isEmpty(fileItems))
127				{
128					for (UploadedFileItem fileItem : fileItems) {
129						JSONObject fileObject = new JSONObject();
130						String fieldName = fileItem.getFieldName();
131						File file = fileItem.getUploadedFile();
132	
133						fileObject.put("Name", fieldName);
134						fileObject.put("ContentType", "image/*");
135						fileObject.put("Content", CommonUtil.encodeFile(file));
136						attachments.put(fileObject);
137					}
138				}
139	
140				LOGGER.info("Length : " + attachments.length());
141	
142				subject = CommonUtil.isEmpty(subject) ? "No Subject" : subject;
143				description = CommonUtil.isEmpty(description) ? "No Description" : description;
144	
145				@SuppressWarnings("deprecation")
146				boolean isPortalAdmin =  CommonUtil.isEmpty(zsoid) ?  false : ServiceOrgHandler.getInstance().isAdminOrModerator(zsoid, currentUser.getZUID());
147				String zsoidStr =  CommonUtil.isEmpty(zsoid) ?  "-" : String.valueOf(zsoid);
148	
149				Locale locale = request.getLocale();
150				String localeStr = locale.getCountry() +  "|" + locale.getLanguage();
151	
152				String content = EmailNotificationContent.getAppticsFeedbackMailContent(description, request.getHeader("User-Agent"), currentUser.getZuid(), zsoidStr, currentUser.getVerifiedEmail(), localeStr, isPortalAdmin);
153				TransmailNotificationUtil.sendMailWithAttachment(subject, content, currentUser.getVerifiedEmail(), AppticsConstants.APPTICSSUPPORTEMAIL, null, null, attachments, new JSONArray());
154	
155				ClientWriter.sendResponse(response, "Your feedback has been successfully.");
156			}
157			catch(AppticsException e)
158			{
159				e.writeToClient(response);
160			}
161			catch (Exception e)
162			{
163				LOGGER.log(Level.SEVERE, "Exception while add application", e);
164				ClientWriter.sendErrorResponse(response, AppticsConstants.UNPROCESSABLE_ENTITY, AppticsConstants.UNPROCESSABLE_ENTITY_MSG);
165			}
166		}
