588		public void addProperty() {
589			LOGGER.log(Level.INFO, "Going to add/update in property table");
590	
591			try {
592				SecurityRequestWrapper secureRequest = (SecurityRequestWrapper) request.getAttribute(SecurityRequestWrapper.class.getName());
593				String jsonVal = secureRequest.getFilteredStreamContent();
594				if (CommonUtil.isEmpty(jsonVal)) {
595					ClientWriter.sendErrorResponse(response, SDK_INVALID_INPUTSTREAM, SDK_INVALID_INPUTSTREAM);
596					return;
597				}
598	
599				JSONObject input = new JSONObject(jsonVal);
600				if (CommonUtil.isEmpty(input) || input.isEmpty()) {
601					ClientWriter.sendResponse(response, "Received an empty object");
602					return;
603				}
604	
605				String name = input.optString("name", null);
606				String value = input.optString("value", null);
607	
608				if (CommonUtil.isEmpty(name) || CommonUtil.isEmpty(value)) {
609					ClientWriter.sendErrorResponse(response, "Missing 'name' or 'value' in request body", "Invalid input");
610					return;
611				}
612	
613				Map<String, Object> ukcolumns = new HashMap<>();
614				ukcolumns.put(PROPKEY, name);
615	
616				if (MickeyUtil.isRowExistInADB(PROPERTIES, PROPID, ukcolumns)) {
617					LOGGER.log(Level.INFO, "Property already available. Updating value.");
