	public void appticsFeedback()
	{
		try
		{
			User currentUser = checkCurrentUser();

			@SuppressWarnings("unchecked")
			ArrayList<UploadedFileItem> fileItems = (ArrayList<UploadedFileItem>) request.getAttribute(SecurityUtil.MULTIPART_FORM_REQUEST);

			if(CommonUtil.isEmpty(subject) && CommonUtil.isEmpty(description) && CommonUtil.isEmpty(fileItems))
			{
				ClientWriter.sendErrorResponse(response, AppticsConstants.INVALID_DATA, AppticsConstants.INVALID_DATA_MSG, AppticsConstants.SC_BAD_REQUEST);
				return;
			}

			JSONArray  attachments = new JSONArray();
			if(!CommonUtil.isEmpty(fileItems))
			{
				for (UploadedFileItem fileItem : fileItems) {
					JSONObject fileObject = new JSONObject();
					String fieldName = fileItem.getFieldName();
					File file = fileItem.getUploadedFile();

					fileObject.put("Name", fieldName);
					fileObject.put("ContentType", "image/*");
					fileObject.put("Content", CommonUtil.encodeFile(file));
					attachments.put(fileObject);
				}
			}

			LOGGER.info("Length : " + attachments.length());

			subject = CommonUtil.isEmpty(subject) ? "No Subject" : subject;
			description = CommonUtil.isEmpty(description) ? "No Description" : description;

			@SuppressWarnings("deprecation")
			boolean isPortalAdmin =  CommonUtil.isEmpty(zsoid) ?  false : ServiceOrgHandler.getInstance().isAdminOrModerator(zsoid, currentUser.getZUID());
			String zsoidStr =  CommonUtil.isEmpty(zsoid) ?  "-" : String.valueOf(zsoid);

			Locale locale = request.getLocale();
			String localeStr = locale.getCountry() +  "|" + locale.getLanguage();

			String content = EmailNotificationContent.getAppticsFeedbackMailContent(description, request.getHeader("User-Agent"), currentUser.getZuid(), zsoidStr, currentUser.getVerifiedEmail(), localeStr, isPortalAdmin);
			TransmailNotificationUtil.sendMailWithAttachment(subject, content, currentUser.getVerifiedEmail(), AppticsConstants.APPTICSSUPPORTEMAIL, null, null, attachments, new JSONArray());

			ClientWriter.sendResponse(response, "Your feedback has been successfully.");
		}
		catch(AppticsException e)
		{
			e.writeToClient(response);
		}
		catch (Exception e)
		{
			LOGGER.log(Level.SEVERE, "Exception while add application", e);
			ClientWriter.sendErrorResponse(response, AppticsConstants.UNPROCESSABLE_ENTITY, AppticsConstants.UNPROCESSABLE_ENTITY_MSG);
		}
	}

