	public void addProperty() {
		LOGGER.log(Level.INFO, "Going to add/update in property table");

		try {
			SecurityRequestWrapper secureRequest = (SecurityRequestWrapper) request.getAttribute(SecurityRequestWrapper.class.getName());
			String jsonVal = secureRequest.getFilteredStreamContent();
			if (CommonUtil.isEmpty(jsonVal)) {
				ClientWriter.sendErrorResponse(response, SDK_INVALID_INPUTSTREAM, SDK_INVALID_INPUTSTREAM);
				return;
			}

			JSONObject input = new JSONObject(jsonVal);
			if (CommonUtil.isEmpty(input) || input.isEmpty()) {
				ClientWriter.sendResponse(response, "Received an empty object");
				return;
			}

			String name = input.optString("name", null);
			String value = input.optString("value", null);

			if (CommonUtil.isEmpty(name) || CommonUtil.isEmpty(value)) {
				ClientWriter.sendErrorResponse(response, "Missing 'name' or 'value' in request body", "Invalid input");
				return;
			}

			Map<String, Object> ukcolumns = new HashMap<>();
			ukcolumns.put(PROPKEY, name);

			if (MickeyUtil.isRowExistInADB(PROPERTIES, PROPID, ukcolumns)) {
				LOGGER.log(Level.INFO, "Property already available. Updating value.");
				updateValue(name, value);
				ClientWriter.sendResponse(response, "Updated existing property.");
				return;
			}

			Row r = new Row(PROPERTIES);
			r.set(PROPKEY, name);
			r.set(PROPVALUE, value);

			ADBHandler.insertRow(r, PROPERTIES, PROPID);
			ClientWriter.sendResponse(response, "Success");

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Unable to add/update property", e);
			ClientWriter.clientFailureResponse("Unable to add/update the property.", response);
		}
	}

	public static int updateValue(final String name, final String value) throws DataAccessException
	{
		Criteria c = new Criteria(Column.getColumn(AppticsConstants.PROPERTIES, AppticsConstants.PROPKEY), name, QueryConstants.EQUAL, false);
		return ADBHandler.update(AppticsConstants.PROPERTIES, c, AppticsConstants.PROPVALUE, value);
	}

	public void migrateTable()
	{
