		try 
		{
			JSONObject reqPayLoad = CommonUtil.getDecryptedAndFilteredStreamContent(request);
			if(CommonUtil.isEmpty(reqPayLoad))
			{
				ClientWriter.sendErrorResponse(response, AppticsConstants.SDK_INVALID_INPUTSTREAM, AppticsConstants.SDK_INVALID_INPUTSTREAM);
				return; 
			}

			JSONObject input = reqPayLoad;

			if(CommonUtil.isEmpty(input) || input.isEmpty())
			{
				ClientWriter.sendResponse(response, "Received an empty object");
				return;
			}

