		LOGGER.log(Level.INFO, "Going to add or get event limit");
		try
		{
			if(CommonUtil.isEmpty(projectID, zsoid ,option))
			{
				ClientWriter.clientFailureResponse(AppticsConstants.SDK_INVALID_DATA, response);
				return;
			}
			JSONObject result = new JSONObject();

			Object obj = null;
			try{
				obj = CommonUtil.setSasThreadLocal(zsoid.toString());
				String temp = ProjectHandler.getAdditionalDetails(projectID);
				if ("get".equals(option)) {
					JSONObject jsonObject = temp != null ? new JSONObject(temp) : new JSONObject();
					result.put("limit", jsonObject.optInt("eventLimit", 1000));
				} else  {
					JSONObject jsonObject = CommonUtil.isEmpty(temp) ?  new JSONObject() : new JSONObject(temp);
					jsonObject.put("eventLimit", limit);
					jsonObject.put("eventGroupLimit", limit);
					new ProjectHandler().updateAdditional(projectID, jsonObject.toString());
					result.put("limit" , "Added successfully");
				}
			}catch (Exception e){
				LOGGER.log(Level.SEVERE, "Exception on adding event limit --->>>", e);
			}finally {
				if (obj != null) {
					CommonUtil.setSasThreadLocalPreObj(obj);
				}
			}
			ClientWriter.sendResponse(response, result);

		}
		catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Unable to add/get event limit", e);
