package com.zoho.apptics.actions;

import com.zoho.apptics.integration.JiraHandler;
import com.zoho.apptics.util.*;
import org.json.JSONArray;
import org.json.JSONObject;

import java.io.IOException;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;

public class JiraAction extends CommonAction {

    private static final long serialVersionUID = 1L;

	private static final Logger LOGGER = Logger.getLogger(JiraAction.class.getName());

    private String code;
    private String state;
    private long apid;
    private String jiraProjectId;
    private String jiraCloudId;

    private boolean validateUser() {
        Long zuId = AppticsIAMUtil.getCurrentUserZUID();
        if (zuId == null) {
            ClientWriter.sendErrorResponse(
                    response,
                    AppticsConstants.UNAUTHORIZED,
                    AppticsConstants.UNAUTHORIZED_MSG
            );
            return false;
        }
        return true;
    }

    /*
     * Returns true when current user role is DEV, DEV_LEAD or PM
     */
    private boolean validateRolesAndPermissions() throws Exception {
        setCurrentUserRoles(projectID, zsoid);
        if (projectRole < 1) {
            ClientWriter.sendErrorResponse(
                    response,
                    AppticsConstants.PERMISSION_DENIED,
                    AppticsConstants.PERMISSION_DENIED_MSG
            );
            return false;
        }
        return true;
    }

    /*
     * Authenticate Jira and store credentials.
     * Redirects to integration page in console on successful authentication.
     */
    public void authenticate() {
        LOGGER.log(Level.INFO, "Jira auth redirection.");

        if (!validateUser()) {
            return;
        }

        String[] stateSplit = state.split("-");
        String portalId = stateSplit[0];
        String projectId = stateSplit[1];
        String mode = stateSplit[2];

        try {
            if (!CommonUtil.isEmpty(code)) {
                boolean authUpdateStatus = new JiraHandler().authenticate(
                        code,
                        request.getRequestURL().toString(),
                        portalId,
                        Long.parseLong(projectId)
                );
            }
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while authenticating Jira", e);
        }

        try {
            response.sendRedirect("/ac/" +portalId + "/" + projectId + "/" + mode + "/settings#integrations/atlassianjira");
        } catch (IOException e) {
            LOGGER.log(Level.SEVERE, "Exception while redirecting after authentication", e);
        }
    }

    public void getToken() {
        try {
            if (!validateUser() || !validateRolesAndPermissions()) {
                ClientWriter.sendErrorResponse(response, AppticsConstants.UNAUTHORIZED, AppticsConstants.UNAUTHORIZED_MSG);
                return;
            }

            JSONObject result = new JSONObject();
            result.put("clientid", PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID));

            ClientWriter.sendResponse(response, result);

