public boolean authenticate(
        String code,
        String redirectUri,
        String zsoId,
        long projectId
) {
    String authExchangeUrl = JIRA_BASE_URL + "/oauth/token";

    String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
    String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);

    if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
        LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
        return false;
    }

    try {
        JSONObject requestBody = new JSONObject();
        requestBody.put("code", code);
        requestBody.put("redirect_uri", redirectUri);
        requestBody.put("grant_type", "authorization_code");
        requestBody.put("client_id", jiraCID);
        requestBody.put("client_secret", jiraClientSecret);

        String authExchangeResponse = new HttpURLConnectionInvoker(true).invokePostHttpURLConnWithRequestBody(
                authExchangeUrl,
                null,
                null,
                requestBody
        );
        LOGGER.log(Level.INFO, authExchangeResponse);
        JSONObject authExchangeJSONResponse = new JSONObject(authExchangeResponse);

        String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
        String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
        String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
        String jiraScope = authExchangeJSONResponse.optString("scope", null);

        if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
            return false;
        }
        addOrUpdateJiraAuth(projectId, zsoId, jiraAccessToken, jiraRefreshToken);

        return true;
    } catch (Exception e) {
        LOGGER.log(Level.SEVERE, "Exception while authenticating Jira", e);
    }
    return false;
}

public List<JiraSites> getJiraSites(String zsoId, Long projectId) {
    try {
        JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
        if (jiraAuth == null) {
            return null;
        }

        JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
            if (CommonUtil.isEmpty(token)) {
                return null;
            }
            String accessibleResourcesUrl = JIRA_BASE_URL + "/oauth/token/accessible-resources";

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + token);
            headers.put("Accept", "application/json");
            LOGGER.log(Level.INFO , "Token {0}", token);
            try {
                String accessibleResourcesResponse = new HttpURLConnectionInvoker(true)
                        .invokeGetHttpURLConn(
                                accessibleResourcesUrl,
                                headers,
                                null
                        );
                return new JSONObject(accessibleResourcesResponse);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
            }
            return null;
        });

        if (jiraResponse == null) {
            return null;
        }

        ArrayList<JiraSites> sites = new ArrayList<>();

        JSONArray resourcesArray = jiraResponse.getJSONArray("data");
        for (int i = 0; i < resourcesArray.length(); i++) {
            JSONObject resource = resourcesArray.getJSONObject(i);
            JiraSites site = new JiraSites(
                    resource.getString("id"),
                    resource.getString("name")
            );
            sites.add(site);
        }

        return sites;

    } catch (Exception e) {
        LOGGER.log(Level.SEVERE, "Exception while fetching Jira sites", e);
    }
    return null;
}

