	private AppPlatform addAppPlatformEntry(long projectID, long aaID, long pid, long mode) throws DataAccessException, AppticsException
	{

		Map<String, Object> ukcolumns = new HashMap<String, Object>();
		ukcolumns.put(AppticsConstants.PROJECTID, projectID);
		ukcolumns.put(AppticsConstants.AAID, aaID);
		ukcolumns.put(AppticsConstants.PID, pid);
		ukcolumns.put(AppticsConstants.MODE, mode);

		Row existingRow = MickeyUtil.getRowIfExists(AppticsConstants.APPPLATFORM, ukcolumns);

		if (!CommonUtil.isEmpty(existingRow))
		{
			LOGGER.log(Level.INFO, "App platform Already Exist. please Try with different platform.");
			return new AppPlatform(existingRow);
//			throw new AppticsException(AppticsConstants.DUPLICATEENTRY, AppticsConstants.DUPLICATEENTRY);
		}

		Row r = new Row(AppticsConstants.APPPLATFORM);
		r.set(AppticsConstants.PROJECTID, projectID);
		r.set(AppticsConstants.AAID, aaID);
		r.set(AppticsConstants.PID, pid);
		r.set(AppticsConstants.MODE, mode);
		r.set(AppticsConstants.DATE, CalendarUtil.currentTimeMillis());

		Integer tagVal = CommonUtil.getNewTag(AppticsConstants.APPPLATFORM, AppticsConstants.APID);

		r.set(AppticsConstants.TAG, tagVal);

		try {
			KeyPair kp = generateRSAKeyPair();
			String privateKey = Base64.encodeBase64String(kp.getPrivate().getEncoded());
			String publicKey = Base64.encodeBase64String(kp.getPublic().getEncoded());

			r.set(AppticsConstants.APP_PRIVATE_KEY, privateKey);
			r.set(AppticsConstants.APP_PUBLIC_KEY, publicKey);
		} catch (NoSuchAlgorithmException e) {
			LOGGER.log(Level.SEVERE, "Application RSA keypair generation failed: ", e);
			throw new AppticsException(AppticsConstants.SDK_OTHER_EXP_STRING, "Failure in creating RSA keypair");
		}

		Long apid = DBHandler.insertRedisCacheRow(r, AppticsConstants.APPPLATFORM, AppticsConstants.APID);
		return new AppPlatform(apid, r);

	}

	private KeyPair generateRSAKeyPair() throws NoSuchAlgorithmException {
		KeyPairGenerator kpg = KeyPairGenerator.getInstance(RSA_ALGORITHM);
		kpg.initialize(RSA_KEY_PAIR_SIZE);
        return kpg.generateKeyPair();
	}

