private String getCloudIdFromAccessibleResources(JSONObject accessibleResources) throws JSONException {
    JSONArray resourcesArray = accessibleResources.getJSONArray("data");

    for (int i = 0; i < resourcesArray.length(); i++) {
        JSONObject resource = resourcesArray.getJSONObject(i);
        JSONArray scopes = resource.getJSONArray("scopes");
        for (int j = 0; j < scopes.length(); j++) {
            if (scopes.getString(j).equals(JIRA_SCOPE)) {
                return resource.getString("id");
            }
        }
    }
    return null;
}

