public static Long checkAndAddApplication(Long projectID, Long pID, String identifier) throws DataAccessException, AppticsException
{
	LOGGER.info("projectID:" + projectID + ", pID:" + pID + ", identifier:" + identifier);
	Long apID = null;
	AdminDBCache adbCache = AdminDBCache.getInstance();
	Long bID = adbCache.getBID(pID);

	Application application = AppHandler.getInstance().getApp(projectID, identifier, bID);

	if(CommonUtil.isEmpty(application) || application.getStatus() == 0)
	{
		LOGGER.log(Level.INFO, "Application is empty. Please register in UI.");
		throw new AppticsException(AppticsConstants.INVALID_APP+"", CommonUtil.isEmpty(application) ? AppticsConstants.INVALID_APP_MSG : AppticsConstants.DISABLED_APP_MSG);
	}

	long aaID = application.getAAID();

	Long modeID = ModeHandler.getModeID(application.getType());	

	AppPlatform appPlatform = AppHandler.getInstance().getAppPlatform(aaID, modeID, pID);
	if(CommonUtil.isEmpty(appPlatform))
	{
		apID = AppHandler.getInstance().addAppPlatform(projectID, aaID, pID, modeID);

		AppHandler.getInstance().updateAppStatus(aaID, 2);

		Integer tag = AppHandler.getInstance().getTagByAPID(apID);
		if(!CommonUtil.isEmpty(tag))
		{
			checkAndAppIdentifier(apID, projectID, identifier, pID, application.getType(), null, tag, null);
		}
		return apID;
	}
	if(appPlatform.status != 1)
	{
		LOGGER.log(Level.INFO, "Application is empty. Please register in UI.");
		throw new AppticsException(AppticsConstants.INVALID_APP+"", appPlatform.status == 0 ? AppticsConstants.DISABLED_APPPLATFORM_MSG : AppticsConstants.DELETED_APPPLATFORM_MSG);
	}

	return appPlatform.apid;
}

